use crate::aap::caps::http_client;

struct Node;

/// The allowlist the host binds behind the HTTP handle. A request outside it
/// traps at the boundary, so URLs are pre-checked here and refused as ordinary
/// fetch failures instead.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Case-insensitive prefix strip that never panics on non-ASCII input.
fn strip_prefix_ci<'a>(s: &'a str, prefix: &str) -> Option<&'a str> {
    match s.get(..prefix.len()) {
        Some(head) if head.eq_ignore_ascii_case(prefix) => Some(&s[prefix.len()..]),
        _ => None,
    }
}

/// Extract the lowercase host of a plain http(s) URL. Returns None for anything
/// this node does not accept: other schemes, userinfo, IPv6 literals, non-numeric
/// ports, or control/whitespace characters.
fn host_of(url: &str) -> Option<String> {
    if url.bytes().any(|b| b <= b' ' || b == 0x7f) {
        return None;
    }
    let rest = strip_prefix_ci(url, "https://")
        .or_else(|| strip_prefix_ci(url, "http://"))?;

    let end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    if authority.is_empty() || authority.contains('@') || authority.contains('[') {
        return None;
    }

    let host = match authority.split_once(':') {
        Some((h, port)) => {
            if port.is_empty() || !port.bytes().all(|b| b.is_ascii_digit()) {
                return None;
            }
            h
        }
        None => authority,
    };

    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            match host_of(&url) {
                Some(host) if ALLOWED_HOSTS.contains(&host.as_str()) => {}
                _ => {
                    failures.push(FetchFailure {
                        url,
                        error: "host not in allowlist".to_string(),
                    });
                    continue;
                }
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch { documents, failures }
    }
}

export!(Node);
